Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "background": "transparent",
  "padding": 5,
  "width": "container",
  "height": "container",
  "title": {
    "text": "M+0 = aquisição (100%) · média ponderada pela safra · 2017-2018",
    "fontSize": 9,
    "fontWeight": 400,
    "color": "#A1A1AA",
    "anchor": "start",
    "offset": 4
  },
  "config": {
    "view": {
      "stroke": null
    },
    "font": "Segoe UI",
    "axis": {
      "domain": false,
      "ticks": false,
      "labelColor": "#C8C8D0",
      "titleColor": "#9aa0aa",
      "labelFontSize": 9,
      "titleFontSize": 10,
      "grid": false
    },
    "legend": {
      "labelColor": "#C8C8D0",
      "titleColor": "#9aa0aa",
      "labelFontSize": 8,
      "titleFontSize": 9,
      "gradientLength": 80
    }
  },
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "filter": "datum[''MesIndice''] != null && datum[''MesIndice''] <= 6 && substring(datum[''Semestre''],0,4) >= ''2017''"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "rect",
        "stroke": "#0A0A0F",
        "strokeWidth": 1,
        "cornerRadius": 2
      },
      "encoding": {
        "color": {
          "field": "Retencao Cohort",
          "type": "quantitative",
          "title": "Retencao",
          "scale": {
            "type": "sqrt",
            "domain": [
              0,
              1
            ],
            "range": [
              "#1a0505",
              "#7f1d1d",
              "#c2410c",
              "#d97706",
              "#ca8a04",
              "#34d399"
            ]
          },
          "legend": {
            "format": ".0%",
            "gradientLength": 80
          }
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "fontSize": 9,
        "fontWeight": 600
      },
      "encoding": {
        "text": {
          "field": "Retencao Cohort",
          "type": "quantitative",
          "format": ".2%"
        },
        "color": {
          "condition": {
            "test": "datum[''Retencao Cohort''] > 0.5",
            "value": "#0A0A0F"
          },
          "value": "#A1A1AA"
        }
      }
    }
  ],
  "encoding": {
    "x": {
      "field": "MesIndice",
      "type": "ordinal",
      "title": "Meses desde a 1a compra (M+0 = aquisicao)",
      "axis": {
        "labelAngle": 0
      }
    },
    "y": {
      "field": "Semestre",
      "type": "ordinal",
      "title": "Semestre de aquisicao",
      "sort": "ascending",
      "axis": {
        "labelFontSize": 10
      }
    },
    "opacity": {
      "condition": {
        "test": "datum.__selected__ === ''off''",
        "value": 0.25
      },
      "value": 1
    },
    "tooltip": [
      {
        "field": "Semestre",
        "title": "Semestre"
      },
      {
        "field": "MesIndice",
        "title": "M+N"
      },
      {
        "field": "Retencao Cohort",
        "type": "quantitative",
        "format": ".3%",
        "title": "Retencao (ponderada)"
      }
    ]
  }
}'
